import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, createUserExamData } from '../services/api';

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    franchiseId: '',
    examName: '',
    date: '',
    durationInMinutes: '',
    status: 'Upcoming',
  });

  const [franchiseName, setFranchiseName] = useState('');
  const [franchiseList, setFranchiseList] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchUserFranchises = async () => {
      setLoading(true);
      try {
        const data = await getAssociatedFranchises();
        if (Array.isArray(data) && data.length > 0) {
          setFranchiseList(data);
          setFranchiseName(data[0].name);
          setExamData((prevData) => ({ ...prevData, franchiseId: data[0]._id }));
        } else {
          setError('No associated franchises found for the user.');
        }
      } catch (error) {
        setError('Failed to fetch the associated franchises.');
      } finally {
        setLoading(false);
      }
    };

    fetchUserFranchises();
  }, []);

  const handleExamDataChange = (e) => {
    const { name, value } = e.target;
    setExamData((prevData) => ({
      ...prevData,
      [name]: name === 'durationInMinutes' ? Number(value) : value,
    }));
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();

    if (!examData.date) {
      setError('Please provide the exam date.');
      return;
    }

    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) {
      setError('Invalid date format.');
      return;
    }

    if (isNaN(examData.durationInMinutes) || examData.durationInMinutes <= 0) {
      setError('Please provide a valid exam duration.');
      return;
    }

    setLoading(true);
    try {
      const formattedDate = examDate.toISOString().split('T')[0];
      const payload = [
        {
          ...examData,
          date: formattedDate,
        },
      ];

      console.log('Payload being sent:', JSON.stringify(payload, null, 2));
      await createUserExamData(payload);

      setSuccess('Exam data created successfully!');
      setExamData({
        franchiseId: examData.franchiseId,
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'Upcoming',
      });
      setError(null);
    } catch (error) {
      console.error('Error creating exam data:', error.response?.data || error.message);
      setError(error.response?.data?.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Associated Franchise: {franchiseName}</h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        <div style={styles.formGroup}>
          <label htmlFor="examName" style={styles.label}>Exam Name</label>
          <input
            type="text"
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="date" style={styles.label}>Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="durationInMinutes" style={styles.label}>Duration (Minutes)</label>
          <input
            type="number"
            name="durationInMinutes"
            value={examData.durationInMinutes}
            onChange={handleExamDataChange}
            required
            min="1"
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="franchiseId" style={styles.label}>Select Franchise</label>
          <select
            name="franchiseId"
            value={examData.franchiseId}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select a franchise</option>
            {franchiseList.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="status" style={styles.label}>Status</label>
          <select
            name="status"
            value={examData.status}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="Upcoming">Upcoming</option>
            <option value="Completed">Completed</option>
            <option value="Cancelled">Cancelled</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

const styles = {
  container: { padding: '20px', backgroundColor: '#f8f9fa', minHeight: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center' },
  header: { fontSize: '2rem', textAlign: 'center', marginBottom: '20px' },
  formTitle: { fontSize: '1.5rem', marginBottom: '15px', textAlign: 'center' },
  form: { width: '100%', maxWidth: '500px', padding: '20px', backgroundColor: 'white', borderRadius: '8px', boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)' },
  formGroup: { marginBottom: '15px' },
  label: { display: 'block', marginBottom: '8px', fontSize: '1rem' },
  input: { width: '100%', padding: '10px', fontSize: '1rem', border: '1px solid #ccc', borderRadius: '4px', boxSizing: 'border-box' },
  submitButton: { width: '100%', padding: '12px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '1.1rem', transition: 'background-color 0.3s ease' },
  loading: { textAlign: 'center', fontSize: '1.2rem', color: '#007bff' },
  error: { color: 'red', fontSize: '1.1rem', textAlign: 'center' },
  success: { color: 'green', fontSize: '1.1rem', textAlign: 'center' },
};

export default AssociatedFranchises;
